CREATE TABLE IF NOT EXISTS wearable_sport_readings(owner_id TEXT NOT NULL,source TEXT NOT NULL,source_record_id TEXT NOT NULL,metric TEXT NOT NULL CHECK(metric IN ('speed','cadence','power','elevation_gain')),start_time TEXT NOT NULL,end_time TEXT NOT NULL,value REAL NOT NULL CHECK(value>=0),unit TEXT NOT NULL,recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(owner_id,source,source_record_id,metric)); CREATE INDEX IF NOT EXISTS idx_wearable_sport_owner_time ON wearable_sport_readings(owner_id,end_time); DROP VIEW IF EXISTS wearable_all_readings; CREATE VIEW wearable_all_readings AS SELECT * FROM wearable_readings UNION ALL SELECT * FROM wearable_extra_readings UNION ALL SELECT * FROM wearable_sport_readings;